ALL = PART1 + PART2 + PART3 + PART4

def write_batch(ids, entries, label):
    assert [e["case_id"] for e in entries] == ids, label + " id set/order mismatch"
    total = 0
    for e in entries:
        assert set(e.keys()) == {"case_id","prediction_text","basis","confidence","trigger"}, e["case_id"]
        assert set(e["trigger"].keys()) == {"changed_main","reserve_used","disputed","reason"}, e["case_id"]
        assert e["basis"].split("\n")[0] == "liuyao", e["case_id"]
        assert 0.0 <= e["confidence"] <= 1.0
        p = os.path.join(OUT_DIR, e["case_id"] + ".json")
        with open(p, "w", encoding="utf-8") as f:
            json.dump(e, f, ensure_ascii=False, indent=1)
        total += os.path.getsize(p)
    # per-batch self-verify: exact ids, parseable, fields complete
    for cid in ids:
        p = os.path.join(OUT_DIR, cid + ".json")
        with open(p, encoding="utf-8") as f:
            d = json.load(f)
        assert d["case_id"] == cid and d["prediction_text"] and d["basis"]
    print(label, "written", len(ids), "bytes", total)
    return total

def main():
    os.makedirs(OUT_DIR, exist_ok=True)
    assert len(ALL) == 40 and len({e["case_id"] for e in ALL}) == 40
    t = 0
    t += write_batch(B13, [e for e in ALL if e["case_id"] in B13], "B13")
    t += write_batch(B14, [e for e in ALL if e["case_id"] in B14], "B14")
    cm = sum(1 for e in ALL if e["trigger"]["changed_main"])
    ru = sum(1 for e in ALL if e["trigger"]["reserve_used"])
    di = sum(1 for e in ALL if e["trigger"]["disputed"])
    print("TOTAL files 40 bytes", t)
